    "exa54@case.edu": {
      "title": "Research Professor, Physics, Case Western Reserve University, Cleveland, Ohio,",
      "bio_html": "<p class=\"bio bio-lead\">Research Professor, Institute of Soft Matter, Theoretical Physics II, HHU, Düsseldorf, Professor, Department of Theoretical Physics, Institute of High Temperatures, Russian Academy of Sciences, Moscow</p><p class=\"bio\">More than 200 scientific articles have been published in about 40 scientific journals. He works as a reviewer in about 30 scientific journals. He supervises about 10 students. He participated in about 100 scientific conferences.</p><p class=\"bio-section-title\">Research interests:</p><p class=\"bio\">Morphological changes of proton-conducting ionomers, conductivity of ionomers, development of water-free conductive nanocomposite ionomers.</p><p class=\"bio\">Actuation of elastomer composites, electrostriction effects in dipole systems, development of nanocomposites with mobility in application areas.</p><p class=\"bio\">Colloid physics, theory of effective interaction potential in electrolytes, phase transition in charged systems, liquid-crystal nucleation processes, critical electrolytes in nanopores.</p><p class=\"bio\">Correlation effects in many-body systems, DNA-DNA condensation effects, protein-DNA interactions.</p><p class=\"bio\">Nucleation processes and template-controlled phase transition in dusty plasma systems.</p><p class=\"bio\">Liquid crystals on curved surfaces, defect-defect interactions, field-dependent morphologies.</p><p class=\"bio\">New composite materials for energy storage applications, Coulomb correlation effects for induced dipoles.</p><p class=\"bio\">Applications of artificial intelligence and deep learning in materials research.</p>",
      "country": "USA",
      "ixtilas": "Physics"
    },
